def subarrays_with_k_distinct(nums, k):
    def at_most_k(limit):
        counts = {}
        left = 0
        total = 0
        for right, num in enumerate(nums):
            counts[num] = counts.get(num, 0) + 1
            while len(counts) > limit:
                left_num = nums[left]
                counts[left_num] -= 1
                if counts[left_num] == 0:
                    del counts[left_num]
                left += 1
            total += right - left + 1
        return total

    return at_most_k(k) - at_most_k(k - 1)

